mapper.select:
select * from (
    select leave_typ type,leave_date begin_date,leave_day days from tb_vacation_detail where user_id=#{userId,jdbcType=VARCHAR} and leave_date between #{beginDate,jdbcType=VARCHAR} and #{endDate,jdbcType=VARCHAR}
    union all
    select '10' type,over_date begin_date,over_day days from tb_over where user_id=#{userId,jdbcType=VARCHAR} and over_date between #{beginDate,jdbcType=VARCHAR} and #{endDate,jdbcType=VARCHAR}
    union all
    select '20' type,trip_date begin_date,trip_day days from tb_trip_detail where user_id=#{userId,jdbcType=VARCHAR} and trip_date between #{beginDate,jdbcType=VARCHAR} and #{endDate,jdbcType=VARCHAR}
    union all
    select '21' type,out_date begin_date,out_day days from tb_out where user_id=#{userId,jdbcType=VARCHAR} and out_date between #{beginDate,jdbcType=VARCHAR} and #{endDate,jdbcType=VARCHAR}
    union all
    select '31' type,check_date begin_date,'1' days from tb_attendance where late>0 and user_id=#{userId,jdbcType=VARCHAR} and check_date between #{beginDate,jdbcType=VARCHAR} and #{endDate,jdbcType=VARCHAR}
    union all
    select '32' type,check_date begin_date,'1' days from tb_attendance where early>0 and user_id=#{userId,jdbcType=VARCHAR} and check_date between #{beginDate,jdbcType=VARCHAR} and #{endDate,jdbcType=VARCHAR}
    union all
    select '33' type,check_date begin_date,'1' days from tb_attendance where absent>0 and user_id=#{userId,jdbcType=VARCHAR} and check_date between #{beginDate,jdbcType=VARCHAR} and #{endDate,jdbcType=VARCHAR}
) a order by a.begin_date

select '加班' type,over_date begin_date,over_day days
from tb_over where user_id=#{userId,jdbcType=VARCHAR}
and `status` in ('97','99')
and over_date between #{beginDate,jdbcType=VARCHAR}
and #{endDate,jdbcType=VARCHAR}
order by begin_date
